bool VulkanPresenter::createImage(Image& out,int w,int h){VkImageCreateInfo ci{VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO};ci.imageType=VK_IMAGE_TYPE_2D;ci.format=VK_FORMAT_R8G8B8A8_UNORM;ci.extent={uint32_t(w),uint32_t(h),1};ci.mipLevels=1;ci.arrayLayers=1;ci.samples=VK_SAMPLE_COUNT_1_BIT;ci.tiling=VK_IMAGE_TILING_OPTIMAL;ci.usage=VK_IMAGE_USAGE_TRANSFER_SRC_BIT|VK_IMAGE_USAGE_TRANSFER_DST_BIT;OK(vkCreateImage(device,&ci,nullptr,&out.image));VkMemoryRequirements req;vkGetImageMemoryRequirements(device,out.image,&req);VkMemoryAllocateInfo ai{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};ai.allocationSize=req.size;ai.memoryTypeIndex=memoryType(req.memoryTypeBits,VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);if(ai.memoryTypeIndex==UINT32_MAX)return false;OK(vkAllocateMemory(device,&ai,nullptr,&out.memory));OK(vkBindImageMemory(device,out.image,out.memory,0));return true;}
void VulkanPresenter::destroyImage(Image& im){if(im.image)vkDestroyImage(device,im.image,nullptr);if(im.memory)vkFreeMemory(device,im.memory,nullptr);im={};}
void VulkanPresenter::clearUploads(){for(auto& s:slots){if(s.mapped)vkUnmapMemory(device,s.memory);if(s.upload)vkDestroyBuffer(device,s.upload,nullptr);if(s.memory)vkFreeMemory(device,s.memory,nullptr);s.mapped=nullptr;s.upload=VK_NULL_HANDLE;s.memory=VK_NULL_HANDLE;destroyImage(s.source);destroyImage(s.scaled);}sourceW=sourceH=factor=0;}
