void VulkanPresenter::close(){if(device){vkDeviceWaitIdle(device);clearUploads();clearSwapchain();for(auto& s:slots){if(s.fence)vkDestroyFence(device,s.fence,nullptr);if(s.acquired)vkDestroySemaphore(device,s.acquired,nullptr);s={};}if(pool)vkDestroyCommandPool(device,pool,nullptr);vkDestroyDevice(device,nullptr);}if(surface)vkDestroySurfaceKHR(instance,surface,nullptr);if(instance)vkDestroyInstance(instance,nullptr);instance=VK_NULL_HANDLE;surface=VK_NULL_HANDLE;device=VK_NULL_HANDLE;physical=VK_NULL_HANDLE;pool=VK_NULL_HANDLE;queue=VK_NULL_HANDLE;presented=0;current=0;}
